"""Write src/data/peak-photos.generated.ts from the credits list made when the photos were fetched.

Photos come from Wikimedia Commons (each article's images for the peak), resized to 900px.
Every photo keeps its author, license and source page so the app can credit it.
Usage: python3 scripts/write-photo-index.py path/to/credits.json
"""
import json
import sys

credits = json.load(open(sys.argv[1]))
lines = [
    '/* Generated by scripts/write-photo-index.py. Photos: Wikimedia Commons, credited per photo. */',
    "import type { PeakPhoto } from '@/lib/types';",
    '',
    'export const PEAK_PHOTOS: Record<string, PeakPhoto[]> = {',
]
for pid in sorted(credits):
    photos = credits[pid]
    if not photos:
        continue
    lines.append(f"  '{pid}': [")
    for p in photos:
        lines.append(
            '    { src: require(%s), author: %s, license: %s, source: %s, w: %d, h: %d },'
            % (
                json.dumps('../../assets/peaks/' + p['file']).replace('"', "'"),
                json.dumps(p['author']),
                json.dumps(p['license']),
                json.dumps(p['source']),
                p['w'],
                p['h'],
            )
        )
    lines.append('  ],')
lines.append('};')
open('src/data/peak-photos.generated.ts', 'w').write('\n'.join(lines) + '\n')
print('peaks with photos:', sum(1 for v in credits.values() if v), 'photos:', sum(len(v) for v in credits.values()))
